import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2.112.4";

const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
const secretKeys = JSON.parse(Deno.env.get("SUPABASE_SECRET_KEYS") || "{}");
const serviceKey = secretKeys.default || Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const db = createClient(supabaseUrl, serviceKey, {
  auth: { persistSession: false, autoRefreshToken: false },
});

const campaignKeys = {
  profile24: "profile_reminder_24h",
  profile72: "profile_reminder_72h",
  platform24: "platform_reminder_24h",
  autoApply3d: "autoapply_reminder_3d",
  feedback7: "feedback_day7",
  premium14: "premium_day14",
  premium30: "premium_day30",
  reactivation21: "reactivation_day21",
};

function clean(value: unknown, max = 240) {
  return String(value ?? "").replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, max);
}

async function secret(name: string) {
  const { data, error } = await db.rpc("get_bot_secret", { secret_name: name });
  if (error || !data) throw Error("configuration_unavailable");
  return String(data);
}

async function telegram(method: string, body: Record<string, unknown>, token: string) {
  const response = await fetch(`https://api.telegram.org/bot${token}/${method}`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(15000),
  });
  const data = await response.json().catch(() => null);
  if (!response.ok || !data?.ok) throw Error(`telegram_${data?.error_code || response.status}`);
  return data.result;
}

function keyboard(rows: any[][]) {
  return { inline_keyboard: [...rows, [{ text: "🔕 Keine weiteren Erinnerungen", callback_data: "engagement:stop" }]] };
}

function messageFor(campaignKey: string) {
  if (campaignKey === campaignKeys.profile24) {
    return {
      text: "🔎 <b>Suchprofil anlegen</b>\n\nLege dein Suchprofil an, damit wir passende Wohnungsangebote für dich finden können.",
      rows: [[{ text: "🔎 Suchprofil anlegen", callback_data: "new" }]],
    };
  }
  if (campaignKey === campaignKeys.profile72) {
    return {
      text: "🔎 <b>Deine Suche ist noch nicht eingerichtet</b>\n\nOhne Suchprofil können wir keine passenden Angebote für dich auswählen.",
      rows: [[{ text: "Jetzt einrichten", callback_data: "new" }]],
    };
  }
  if (campaignKey === campaignKeys.platform24) {
    return {
      text: "🔗 <b>Plattform verbinden</b>\n\nDein Suchprofil ist bereit. Verbinde jetzt eine Plattform, damit die automatische Bewerbung eingerichtet werden kann.",
      rows: [[{ text: "🔗 Plattform verbinden", callback_data: "platforms" }]],
    };
  }
  if (campaignKey === campaignKeys.autoApply3d) {
    return {
      text: "⚡ <b>AutoApply aktivieren</b>\n\nAktiviere AutoApply, damit passende Bewerbungen automatisch über deine verbundenen Plattformen versendet werden können.",
      rows: [[{ text: "⚡ AutoApply aktivieren", callback_data: "platforms:on" }]],
    };
  }
  if (campaignKey === campaignKeys.feedback7) {
    return {
      text: "💬 <b>Kurze Rückmeldung?</b>\n\nWie läuft deine Wohnungssuche bisher?",
      rows: [
        [{ text: "👍 Alles gut", callback_data: "engagement:feedback:good" }],
        [{ text: "🔧 Optimieren", callback_data: "engagement:feedback:improve" }],
        [{ text: "⚠️ Problem melden", callback_data: "engagement:feedback:problem" }],
      ],
    };
  }
  if (campaignKey === campaignKeys.premium14) {
    return {
      text: "💎 <b>Mehr aus deiner Wohnungssuche machen</b>\n\nMit Premium erhältst du:\n\n✅ automatische Bewerbungen auf passende Angebote\n✅ bis zu 4 Suchprofile statt 1 im Free-Tarif\n✅ weniger manuelle Schritte bei der Wohnungssuche\n✅ automatisierte Verarbeitung über verbundene Plattformen",
      rows: [[{ text: "💎 Premium-Vorteile ansehen", callback_data: "premium" }]],
    };
  }
  if (campaignKey === campaignKeys.premium30) {
    return {
      text: "💎 <b>Deine Suche kann noch einfacher werden</b>\n\nPremium übernimmt mehr Arbeit für dich:\n\n🤖 passende Bewerbungen automatisch versenden\n🔎 bis zu 4 Suchprofile statt 1 im Free-Tarif verwalten\n⚡ weniger Angebote manuell bearbeiten\n🔗 verbundene Plattformen automatisiert nutzen",
      rows: [[{ text: "Premium aktivieren", callback_data: "premium" }]],
    };
  }
  if (campaignKey === campaignKeys.reactivation21) {
    return {
      text: "🏠 <b>Deine Wohnungssuche wartet</b>\n\nDein Suchprofil ist noch aktiv. Prüfe kurz, ob deine Suchkriterien weiterhin passen.",
      rows: [[{ text: "🔎 Suchprofil öffnen", callback_data: "profile" }]],
    };
  }
  if (campaignKey.startsWith("reactivation_monthly_")) {
    return {
      text: "🏠 <b>Suche fortsetzen?</b>\n\nMöchtest du deine Wohnungssuche wieder aufnehmen?",
      rows: [[{ text: "🔎 Suche öffnen", callback_data: "profile" }]],
    };
  }
  return null;
}

function isPremium(user: any, subscription: any) {
  const now = Date.now();
  if (user?.plan_override === "free") return false;
  if (user?.plan_override === "premium" && (!user.plan_override_expires_at || Date.parse(user.plan_override_expires_at) > now)) return true;
  if (user?.referral_bonus_until && Date.parse(user.referral_bonus_until) > now) return true;
  return !!subscription && ["active", "trialing"].includes(String(subscription.status)) &&
    (!subscription.current_period_end || Date.parse(subscription.current_period_end) > now);
}

async function materialize(now: string) {
  const { data, error } = await db.rpc("materialize_engagement_notifications", { p_now: now, p_limit: 200 });
  if (error) throw Error(`materialize_${error.code || "failed"}`);
  return Number(data || 0);
}

async function process(botToken: string) {
  const staleAt = new Date(Date.now() - 15 * 60_000).toISOString();
  await db.from("user_engagement_notifications")
    .update({ status: "pending", claimed_at: null, updated_at: new Date().toISOString() })
    .eq("status", "processing")
    .lt("claimed_at", staleAt);

  const { data: rows, error } = await db.from("user_engagement_notifications")
    .select("id,user_id,campaign_key,attempts")
    .eq("status", "pending")
    .lte("available_at", new Date().toISOString())
    .order("scheduled_at", { ascending: true })
    .order("created_at", { ascending: true })
    .limit(40);
  if (error) throw Error("engagement_read_failed");
  if (!rows?.length) return { queued: 0, sent: 0, cancelled: 0, failed: 0, deferred: 0 };

  const userIds = [...new Set(rows.map((row: any) => String(row.user_id)))];
  const [{ data: users, error: userError }, { data: subscriptions, error: subError }] = await Promise.all([
    db.from("bot_users").select("id,chat_id,is_active,engagement_notifications_enabled,plan_override,plan_override_expires_at,referral_bonus_until").in("id", userIds),
    db.from("user_subscriptions").select("user_id,status,current_period_end").in("user_id", userIds),
  ]);
  if (userError || subError) throw Error("engagement_user_read_failed");
  const userMap = new Map((users || []).map((user: any) => [String(user.id), user]));
  const subscriptionMap = new Map((subscriptions || []).map((sub: any) => [String(sub.user_id), sub]));
  const recentCutoff = new Date(Date.now() - 7 * 24 * 60 * 60_000).toISOString();
  const { data: recentRows, error: recentError } = await db.from("user_engagement_notifications")
    .select("user_id,sent_at")
    .in("user_id", userIds)
    .eq("status", "sent")
    .gte("sent_at", recentCutoff)
    .order("sent_at", { ascending: false });
  if (recentError) throw Error("engagement_pacing_read_failed");
  const recentlySent = new Map<string, string>();
  for (const recent of recentRows || []) {
    if (!recentlySent.has(String(recent.user_id))) recentlySent.set(String(recent.user_id), String(recent.sent_at));
  }
  let sent = 0, cancelled = 0, failed = 0, deferred = 0;

  for (const row of rows) {
    const user = userMap.get(String(row.user_id));
    const campaign = messageFor(String(row.campaign_key));
    const premiumCampaign = String(row.campaign_key).startsWith("premium_") || String(row.campaign_key) === campaignKeys.autoApply3d || String(row.campaign_key) === campaignKeys.platform24;
    if (!user || !user.chat_id || Number(user.chat_id) <= 0 || !user.is_active || !user.engagement_notifications_enabled || !campaign || (premiumCampaign && !isPremium(user, subscriptionMap.get(String(row.user_id))))) {
      await db.from("user_engagement_notifications").update({ status: "cancelled", updated_at: new Date().toISOString(), last_error: "not_eligible" }).eq("id", row.id).eq("status", "pending");
      cancelled += 1;
      continue;
    }
    const userId = String(row.user_id);
    const previousSentAt = recentlySent.get(userId);
    if (previousSentAt) {
      const nextAvailable = new Date(Math.max(Date.now() + 60_000, Date.parse(previousSentAt) + 7 * 24 * 60 * 60_000)).toISOString();
      await db.from("user_engagement_notifications").update({ available_at: nextAvailable, updated_at: new Date().toISOString(), last_error: "paced_7d" }).eq("id", row.id).eq("status", "pending");
      deferred += 1;
      continue;
    }
    const attempts = Number(row.attempts || 0) + 1;
    const { data: claimed, error: claimError } = await db.from("user_engagement_notifications")
      .update({ status: "processing", attempts, claimed_at: new Date().toISOString(), updated_at: new Date().toISOString(), last_error: null })
      .eq("id", row.id).eq("status", "pending").select("id").maybeSingle();
    if (claimError || !claimed) continue;
    try {
      await telegram("sendMessage", {
        chat_id: Number(user.chat_id),
        text: campaign.text,
        parse_mode: "HTML",
        disable_web_page_preview: true,
        reply_markup: keyboard(campaign.rows),
      }, botToken);
      await db.from("user_engagement_notifications").update({ status: "sent", sent_at: new Date().toISOString(), updated_at: new Date().toISOString(), last_error: null }).eq("id", row.id);
      recentlySent.set(userId, new Date().toISOString());
      sent += 1;
    } catch (error) {
      const errorMessage = clean((error as Error)?.message || error);
      const terminal = attempts >= 5 || /telegram_(400|403)\b/.test(errorMessage);
      await db.from("user_engagement_notifications").update({ status: terminal ? "failed" : "pending", available_at: new Date(Date.now() + Math.min(attempts * 5, 30) * 60_000).toISOString(), updated_at: new Date().toISOString(), last_error: errorMessage }).eq("id", row.id);
      failed += 1;
    }
  }
  return { queued: rows.length, sent, cancelled, failed, deferred };
}

async function run() {
  const [internalSecret, botToken] = await Promise.all([secret("internal_worker_secret"), secret("telegram_bot_token_runtime")]);
  const now = new Date().toISOString();
  const materialized = await materialize(now);
  const result = await process(botToken);
  return { ok: true, materialized, ...result };
}

Deno.serve(async (request) => {
  try {
    if (request.method !== "POST") return new Response("method not allowed", { status: 405 });
    const internalSecret = await secret("internal_worker_secret");
    if (request.headers.get("x-internal-secret") !== internalSecret) return new Response("unauthorized", { status: 401 });
    const body = await request.json().catch(() => ({}));
    if (body?.action === "health") return Response.json({ ok: true, mode: "telegram-engagement" });
    return Response.json(await run());
  } catch (error) {
    console.error("telegram_engagement", String(error));
    return Response.json({ ok: false, error: "telegram_engagement_failed" }, { status: 503 });
  }
});

